/* ---------------- 4-1. 박진감 장치 (11-26 사용자 "조금 더 박진감 있게, 더 재밌게") ----------------
 * 모든 게임 공통. 화면 흔들림은 늘리지 않음(11-23 멀미 → JE.motion 그대로), 소리·색·글자로 긴장감을 준다.
 *  K.danger(v, vis)   : 위기 정도 0~1 을 매 프레임 알려 주면 빨간 가장자리 + 심장 소리(쿵쿵, 위기일수록 빨라짐). vis=false 면 소리만
 *  K.speedUp(text)    : '속도 UP!' 큰 글자 + 쉭 소리 (게임이 단계 올릴 때)
 *  K.lucky(text,x,y)  : 깜짝 보상 금빛 글자 + 반짝 소리
 *  K.rush(k)          : 연속 콤보 소리 높이 (0,1,2... 올라감)
 *  자동: 점수가 내 최고점에 다가가면 BEST 아래 진행 줄이 차오르고(85%부터 깜빡), 넘는 순간 '신기록 돌파!' + 색종이 (한 판 한 번) */
const TH = K.thrill = { noCross: false, d: 0, dT: 0, vis: true, beatT: 0, ph: 0, run: null };
JE.sfx.heart = (v = 0.5) => { JE.audio.tone(78, 0.1, 'sine', 0.22 + v * 0.2, 0.6); JE.audio.tone(64, 0.12, 'sine', 0.18 + v * 0.16, 0.6, 0.15); };
JE.sfx.whoosh = () => { JE.audio.noise(0.28, 0.16, 900); JE.audio.tone(300, 0.25, 'sawtooth', 0.05, 3); JE.audio.tone(660, 0.18, 'triangle', 0.08, 1.6, 0.14); };
JE.sfx.lucky = () => { [1047, 1319, 1568, 2093].forEach((f, i) => JE.audio.tone(f, 0.14, 'triangle', 0.11, 1.01, i * 0.05)); JE.audio.noise(0.15, 0.06, 5000, 0.05); };
JE.sfx.rush = (k = 0) => { const f = 392 * Math.pow(1.0595, Math.min(k, 14) * 2); JE.audio.tone(f, 0.09, 'square', 0.06, 1.25); JE.audio.tone(f * 2, 0.07, 'triangle', 0.05, 1, 0.04); };
K.danger = function (v, vis = true) { v = Math.max(0, Math.min(1, +v || 0)); if (v >= TH.dT) { TH.dT = v; TH.vis = vis; } };
K.speedUp = function (text = '속도 UP!', y) {
  K.pop(text, JE.W / 2, y || JE.H * 0.42, { size: 36, c1: '#ffe1c2', c2: '#ff7a3d', life: 1.1, peek: false });
  JE.sfx.whoosh(); JE.haptic('soft'); K.flash(0.18, '255,170,90');
};
K.lucky = function (text, x = JE.W / 2, y = JE.H * 0.38, o = {}) {
  K.pop(text, x, y, Object.assign({ size: 32, c1: '#fffbe0', c2: '#ffc21f', life: 1.2 }, o));
  JE.sfx.lucky(); JE.haptic('success'); K.flash(0.22, '255,220,90');
  JE.fx.burst && JE.fx.burst(x, y, '#ffd23f', 16);
};
K.rush = k => JE.sfx.rush(k);
const openModal = () => !!document.querySelector('.je-ov');
function thrillUpdate(dt) {
  TH.d += (TH.dT - TH.d) * Math.min(1, dt * 6); TH.dT = 0; TH.ph += dt;
  if (TH.d > 0.3 && !openModal()) {
    TH.beatT -= dt;
    if (TH.beatT <= 0) { TH.beatT = 1.0 - TH.d * 0.5; JE.sfx.heart(TH.d); if (TH.d > 0.75) JE.haptic('tap'); }
  } else TH.beatT = Math.min(TH.beatT, 0.25);
}
function thrillRender(c) {
  if (TH.d < 0.03 || !TH.vis) return;
  const W = JE.W, H = JE.H, pulse = 0.7 + 0.3 * Math.sin(TH.ph * (5 + TH.d * 5)), a = TH.d * 0.42 * pulse, e = Math.min(W, H) * (0.16 + TH.d * 0.1);
  c.save();
  const side = (x0, y0, x1, y1, x, y, w, h) => { const g = c.createLinearGradient(x0, y0, x1, y1); g.addColorStop(0, `rgba(255,60,90,${a})`); g.addColorStop(1, 'rgba(255,60,90,0)'); c.fillStyle = g; c.fillRect(x, y, w, h); };
  side(0, 0, e, 0, 0, 0, e, H); side(W, 0, W - e, 0, W - e, 0, e, H); side(0, H, 0, H - e, 0, H - e, W, e); side(0, 0, 0, e * 0.6, 0, 0, W, e * 0.6);
  c.restore();
}
// 최고점 쫓기 + 신기록 돌파 (B.hudRow 를 감싸서 10종 모두 자동)
const hudRow0 = B.hudRow;
B.hudRow = function (c, rowY, score, best, W = JE.W) {
  const r = hudRow0.apply(this, arguments);
  try { chase(c, rowY, +score || 0, +best || 0, W); } catch (e) {}
  return r;
};
function chase(c, rowY, score, best, W) {
  let R = TH.run;
  if (!R || score < R.last - 0.5) R = TH.run = { best0: best, crossed: false, near: false, last: score };
  R.last = score;
  if (openModal() || !(R.best0 >= 30)) return;
  const k = score / R.best0;
  if (!R.crossed && score > R.best0 + 0.5) {
    R.crossed = true;
    if (TH.noCross) return; // 게임이 자기 돌파 연출을 가진 경우(블락풍)
    K.pop('신기록 돌파!', W / 2, JE.H * 0.3, { size: 44, c1: '#fff6b0', c2: '#ffb21f', life: 1.6 });
    K.confetti(55); JE.sfx.fanfare(); JE.haptic('success'); K.flash(0.3, '255,220,90');
  } else if (!R.near && k >= 0.85 && k < 1) {
    R.near = true; JE.sfx.rush(6);
    K.pop('최고점이 코앞!', W / 2, rowY + 96, { size: 24, c1: '#fff', c2: '#ff9a4d', life: 1.1, peek: false });
  }
  if (k < 0.4 || R.crossed) return;
  // BEST 숫자 아래 차오르는 줄 (최고점까지 얼마나 왔는지)
  const s = JE.safe, bx = 16 + s.left + 4, bw = 64, y = rowY + 17, kk = Math.min(1, k);
  const blink = kk >= 0.85 ? 0.55 + 0.45 * Math.sin(TH.ph * 12) : 1;
  c.save(); c.lineCap = 'round';
  c.strokeStyle = 'rgba(43,43,43,.15)'; c.lineWidth = 4; c.beginPath(); c.moveTo(bx, y); c.lineTo(bx + bw, y); c.stroke();
  c.globalAlpha = blink; c.strokeStyle = kk >= 0.85 ? '#ff5d3a' : '#ff9a4d'; c.beginPath(); c.moveTo(bx, y); c.lineTo(bx + bw * kk, y); c.stroke();
  c.restore();
}

/* ---------------- 5. 그림 도우미 ---------------- */

// 11-26 깜짝 보상: 황금 젤리 (꾹 맞추면 +100, 그냥 쌓아도 +30)
const gold = n >= 5 && n >= (G.nextGold || 0) && G.feverT <= 0;
if (gold) G.nextGold = n + 7 + Math.floor(G.rng() * 5); else if (!G.nextGold) G.nextGold = 5 + Math.floor(G.rng() * 3);
G.mover = { x: -dir * range, dir, speed, range, yWorld: towerTopY() + L.FH * HOVER, sq: { v: 1, vel: 0 }, gold };
if (gold) { JE.sfx.lucky && JE.sfx.lucky(); fxPop('황금 젤리! 꾹 맞추면 +100', L.cx, L.H * 0.5, { size: 24, c1: '#fffbe0', c2: '#ffc21f', life: 1.2, rot: 0 }); }

// 11-26 아슬아슬 생존 보너스 + 황금 젤리
if (lit === 0) pts += 20;
if (f.gold) pts += perfect ? 100 : 30;
if (G.feverT > 0) pts *= 2;

